var pl;
(function( pl ) {

	// Largest number of elements one call may build.
	var MAX_LENGTH = 1000000;

	// Walk a list term; returns the elements and the term that ends the list.
	var walk = function( list ) {
		var items = [];
		var pointer = list;
		while( pl.type.is_term( pointer ) && pointer.indicator === "./2" ) {
			items.push( pointer.args[0] );
			pointer = pointer.args[1];
		}
		return { items: items, tail: pointer };
	};

	// Build a list term from an array.
	var build = function( items ) {
		var list = new pl.type.Term( "[]", [] );
		for( var i = items.length - 1; i >= 0; i-- )
			list = new pl.type.Term( ".", [items[i], list] );
		return list;
	};

	// Read a proper list into an array. Throws the matching error and returns null otherwise.
	var read = function( thread, atom, list ) {
		var walked = walk( list );
		if( pl.type.is_variable( walked.tail ) ) {
			thread.throw_error( pl.error.instantiation( atom.indicator ) );
			return null;
		}
		if( !pl.type.is_term( walked.tail ) || walked.tail.indicator !== "[]/0" ) {
			thread.throw_error( pl.error.type( "list", list, atom.indicator ) );
			return null;
		}
		return walked.items;
	};

	// Check that an argument is an integer. Throws the matching error and returns false otherwise.
	var check_integer = function( thread, atom, term ) {
		if( pl.type.is_variable( term ) ) {
			thread.throw_error( pl.error.instantiation( atom.indicator ) );
			return false;
		}
		if( !pl.type.is_integer( term ) ) {
			thread.throw_error( pl.error.type( "integer", term, atom.indicator ) );
			return false;
		}
		return true;
	};

	// Check that an argument is an integer that is not negative.
	var check_count = function( thread, atom, term ) {
		if( !check_integer( thread, atom, term ) ) return false;
		if( term.value < 0 ) {
			thread.throw_error( pl.error.domain( "not_less_than_zero", term, atom.indicator ) );
			return false;
		}
		return true;
	};

	// Wrap a JavaScript integer as a Prolog integer.
	var integer = function( value ) {
		return new pl.type.Num( value, false );
	};

	// Smallest and largest value of an array of integer terms.
	var bounds = function( items ) {
		var min = items[0].value, max = min;
		for( var i = 1; i < items.length; i++ ) {
			if( items[i].value < min ) min = items[i].value;
			if( items[i].value > max ) max = items[i].value;
		}
		return [min, max];
	};

	// Move the first shift elements of an array behind the rest.
	// A negative shift moves elements from the end to the front.
	// The shift may be larger than the array, so it wraps around.
	// The input array is not changed.
	// An empty array comes back as it is.
	var rotate = function( items, shift ) {
		if( items.length === 0 ) return items;
		var offset = ( ( shift % items.length ) + items.length ) % items.length;
		return items.slice( offset ).concat( items.slice( 0, offset ) );
	};

	var predicates = function() {

		// Unify a computed result with the output argument.
		var give = function( thread, point, result, expected ) {
			thread.prepend( [new pl.type.State( point.goal.replace( new pl.type.Term( "=", [result, expected] ) ), point.substitution, point )] );
		};

		return {

			// range_list/3
			"range_list/3": function( thread, point, atom ) {
				var low = atom.args[0], high = atom.args[1];
				if( !check_integer( thread, atom, low ) || !check_integer( thread, atom, high ) ) return;
				if( low.value > high.value ) return;
				if( high.value - low.value >= MAX_LENGTH ) {
					thread.throw_error( pl.error.representation( "max_list_length", atom.indicator ) );
					return;
				}
				var numbers = [];
				for( var i = low.value; i <= high.value; i++ )
					numbers.push( integer( i ) );
				give( thread, point, build( numbers ), atom.args[2] );
			},

			// range_step/4
			"range_step/4": function( thread, point, atom ) {
				var low = atom.args[0], high = atom.args[1], step = atom.args[2];
				if( !check_integer( thread, atom, low ) || !check_integer( thread, atom, high ) || !check_integer( thread, atom, step ) ) return;
				if( step.value <= 0 ) {
					thread.throw_error( pl.error.domain( "positive_integer", step, atom.indicator ) );
					return;
				}
				if( ( high.value - low.value ) / step.value >= MAX_LENGTH ) {
					thread.throw_error( pl.error.representation( "max_list_length", atom.indicator ) );
					return;
				}
				var numbers = [];
				for( var v = low.value; v <= high.value; v += step.value )
					numbers.push( integer( v ) );
				give( thread, point, build( numbers ), atom.args[3] );
			},

			// list_bounds/3
			"list_bounds/3": function( thread, point, atom ) {
				var items = read( thread, atom, atom.args[0] );
				if( items === null ) return;
				for( var i = 0; i < items.length; i++ )
					if( !check_integer( thread, atom, items[i] ) ) return;
				if( items.length === 0 ) return;
				var found = bounds( items );
				var both = new pl.type.Term( ",", [
					new pl.type.Term( "=", [integer( found[0] ), atom.args[1]] ),
					new pl.type.Term( "=", [integer( found[1] ), atom.args[2]] )
				] );
				thread.prepend( [new pl.type.State( point.goal.replace( both ), point.substitution, point )] );
			},

			// split_at/4
			"split_at/4": function( thread, point, atom ) {
				var count = atom.args[0];
				if( !check_count( thread, atom, count ) ) return;
				var items = read( thread, atom, atom.args[1] );
				if( items === null ) return;
				var cut = Math.min( count.value, items.length );
				var both = new pl.type.Term( ",", [
					new pl.type.Term( "=", [build( items.slice( 0, cut ) ), atom.args[2]] ),
					new pl.type.Term( "=", [build( items.slice( cut ) ), atom.args[3]] )
				] );
				thread.prepend( [new pl.type.State( point.goal.replace( both ), point.substitution, point )] );
			},

			// rotate_list/3
			"rotate_list/3": function( thread, point, atom ) {
				if( !check_integer( thread, atom, atom.args[0] ) ) return;
				var items = read( thread, atom, atom.args[1] );
				if( items === null ) return;
				give( thread, point, build( rotate( items, atom.args[0].value ) ), atom.args[2] );
			}

		};
	};

	var exports = ["range_list/3", "range_step/4", "list_bounds/3", "split_at/4", "rotate_list/3"];

	if( typeof module !== 'undefined' ) {
		module.exports = function( p ) {
			pl = p;
			new pl.type.Module( "ranges", predicates(), exports );
		};
	} else {
		new pl.type.Module( "ranges", predicates(), exports );
	}

})( pl );
